<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\Html;$this->title='球队';?><h1>参赛球队</h1><form action="<?= Html::encode(\yii\helpers\Url::to(['index'])) ?>" method="get" class="wc-filters"><input name="q" placeholder="搜索球队" value="<?= Html::encode(Yii::$app->request->get('q','')) ?>"><button>搜索</button></form><div class="grid"><?php foreach($teams as $team):?><article class="card"><h2><?= Html::a(Html::encode($team->name),['view','id'=>$team->id]) ?></h2><p><?= Html::encode($team->fifa_code) ?></p></article><?php endforeach ?></div><?= yii\widgets\LinkPager::widget(['pagination'=>$pages]) ?>